/* Original teaching examples for AI PATH. Age bands are flexible learning options. */
(() => {
  'use strict';
  const c = (story, example, question, choices, answer, hint) => ({story,example,question,choices,answer,hint});
  const q = (question,choices,answer,hint) => ({question,choices,answer,hint});
  const goals = [
    {id:'choose',title:'От мечты к понятной цели',rule:'Цель — это то, что ты хочешь попробовать или создать. Выбери результат, который можно узнать и который действительно важен тебе.',quiz:q('Как понять, что цель стала конкретнее?',['Можно представить результат и объяснить его','В ней нет ни одного действия','Её выбрал кто-то другой'],0,'Представь, что покажешь после работы.'),cases:{
      '6-9':c('Маша любит рисовать и хочет сделать подарок бабушке.','Нарисовать открытку с цветком и подарить её в воскресенье.','Какую цель Маше будет проще узнать, когда она готова?',['Стать лучшей во всём','Нарисовать открытку с цветком','Никогда не пользоваться карандашами'],1,'Ищи понятный рисунок, который можно показать.'),
      '10-13':c('Дане нравится создавать игры. Он хочет сделать первую игру для друзей.','Сделать короткую игру, в которой персонаж собирает три звезды.','Какая цель поможет начать проект?',['Сделать короткую игру со сбором трёх звёзд','Сразу создать все игры мира','Ничего не менять в любимой игре'],0,'Цель должна описывать конкретный результат.'),
      '14-17':c('Лена хочет попробовать себя в дизайне и собрать первую работу для портфолио.','Создать один макет страницы для учебного проекта и показать его другу.','Как сформулировать ближайшую цель?',['Сразу стать известным дизайнером','Сделать один макет и получить отзыв','Изучить весь дизайн за один вечер'],1,'Выбери достижимый результат для первого проекта.') }},
    {id:'steps',title:'Большая цель — маленькие шаги',rule:'Разбей цель на небольшие действия. Первый шаг должен быть понятным и достаточно маленьким, чтобы его можно было начать.',quiz:q('Зачем делить большую задачу на шаги?',['Чтобы было понятно, с чего начать','Чтобы никогда не отдыхать','Чтобы сразу сделать всё идеально'],0,'Подумай, что помогает начать трудное дело.'),cases:{
      '6-9':c('Илья хочет собрать корабль из конструктора, но деталей очень много.','Сначала выбрать детали для корпуса, затем собрать его.','Что можно сделать первым?',['Высыпать всё и бросить','Сначала найти детали для корпуса','Ждать, пока корабль появится сам'],1,'Первый шаг — маленькое действие с деталями.'),
      '10-13':c('Саша хочет сделать комикс о своём герое и пока не знает, с чего начать.','Придумать героя, набросать три кадра, затем добавить реплики.','Какой первый шаг подходит?',['Нарисовать сразу целую книгу','Придумать героя и нарисовать его','Удалить все карандаши'],1,'Выбери действие, которое можно выполнить отдельно.'),
      '14-17':c('Ника хочет подготовить небольшое портфолио своих работ.','Сначала выбрать одну работу, потом описать её и добавить изображение.','С чего разумнее начать?',['Отобрать одну работу и записать, что в ней сделано','Сделать десять проектов за вечер','Не начинать без идеального сайта'],0,'Не обязательно решать всё сразу.') }},
    {id:'plan',title:'План и поддержка',rule:'Реши, когда и где сделаешь следующий шаг, и кто может помочь. План — подсказка, его можно менять.',quiz:q('Что делает план полезнее?',['Понятный следующий шаг и подходящее время','Обещание никогда не ошибаться','Отказ от помощи'],0,'Подумай о действии и удобном моменте.'),cases:{
      '6-9':c('Аня хочет посадить фасоль, но ей нужна помощь с землёй и водой.','В субботу попросить взрослого помочь посадить фасоль.','Какой план подойдёт?',['Попросить взрослого помочь в субботу','Посадить без земли и воды','Спрятать семена и ничего не делать'],0,'Вспомни, кто может помочь и когда.'),
      '10-13':c('Артём хочет записать короткое видео, но ещё не умеет монтировать.','После школы снять один кадр и попросить друга показать монтаж.','Какой следующий шаг поможет?',['Снять один кадр и попросить показать монтаж','Обещать закончить фильм немедленно','Не задавать вопросы никому'],0,'План может включать помощь другого человека.'),
      '14-17':c('Вика готовит школьный проект и хочет узнать мнение наставника.','Выделить время на черновик и заранее договориться об обратной связи.','Какой вариант превращает идею в план?',['Сделать черновик и договориться об отзыве','Ждать идеального вдохновения','Скрыть работу до последнего дня'],0,'Назначь действие и найди поддержку.') }},
    {id:'obstacles',title:'Если что-то не получилось',rule:'Ошибка не означает провал. Остановись, попробуй другой шаг или попроси поддержки; цель и сроки можно пересмотреть.',quiz:q('Что делать, если план не сработал?',['Уточнить, что мешает, и попробовать другой шаг','Ругать себя и отказаться от отдыха','Считать, что учиться больше нельзя'],0,'План можно поправить, а за помощью — обратиться.'),cases:{
      '6-9':c('Башня Али падает, когда она ставит последний кубик.','Попробовать сделать основание шире и попросить подсказку.','Что поможет Али?',['Попробовать более широкое основание','Решить, что играть нельзя','Сломать все кубики'],0,'Посмотри, как сделать башню устойчивее.'),
      '10-13':c('Максим запланировал снять видео на улице, но пошёл сильный дождь.','Перенести съёмку или сделать безопасный кадр дома.','Как поступить с планом?',['Перенести съёмку или снять кадр дома','Снимать на улице несмотря на опасную погоду','Считать идею навсегда испорченной'],0,'Обстоятельства изменились — план тоже может измениться.'),
      '14-17':c('Полина не успевает закончить проект из-за неожиданной нагрузки в школе.','Уменьшить объём первой версии и обсудить новый срок.','Что поможет продолжить?',['Согласовать меньший объём или срок','Отказаться от сна ради идеала','Никому не говорить и потерять срок'],0,'Подумай о гибком и бережном изменении плана.') }},
    {id:'progress',title:'Замечаем прогресс',rule:'Сравни результат со своей целью: что уже получилось, чему научился и что можно изменить? Отмечай усилия и маленькие шаги.',quiz:q('Как оценить свой прогресс?',['Посмотреть, что получилось и чему научился','Сравнивать себя только с чужими успехами','Замечать только ошибки'],0,'Сравни свой результат со своим планом.'),cases:{
      '6-9':c('Марк уже собрал корпус кораблика, но ещё не добавил парус.','Отметить готовый корпус и решить, как сделать парус.','Что Марк может заметить?',['Корпус готов, следующий шаг — парус','Ничего не получилось, потому что паруса ещё нет','Нужно сразу купить другой конструктор'],0,'Посмотри и на готовую часть, и на следующий шаг.'),
      '10-13':c('У Кати готово три кадра комикса, но в одном реплика непонятна.','Порадоваться трём кадрам и поправить одну реплику.','Как проверить работу?',['Сохранить удачные кадры и уточнить реплику','Удалить всё из-за одной ошибки','Не смотреть готовые кадры'],0,'Ошибка может подсказать небольшое улучшение.'),
      '14-17':c('Тимур показал черновик портфолио другу и получил два полезных замечания.','Записать, что удалось, и выбрать одно улучшение для следующей версии.','Как использовать отзыв?',['Выбрать полезное замечание и улучшить работу','Считать любой комментарий оценкой личности','Менять всё одновременно без разбора'],0,'Обратная связь помогает выбрать конкретный следующий шаг.') }}
  ];
  const time = [
    {id:'notice',title:'Замечаем своё время',rule:'У дня есть разные части: учёба, еда, движение, сон, отдых и любимые дела. Сначала посмотри, как устроен день, без оценок и спешки.',quiz:q('Что важно оставить в расписании?',['Только занятия без остановки','Отдых, сон и другие важные дела','Только самые сложные задачи'],1,'У дня есть время для восстановления и разных дел.'),cases:{
      '6-9':c('У Оли после школы обед, прогулка и чтение с папой.','Вместе нарисовать, что обычно происходит после школы.','Что Оле стоит учесть в плане?',['Только чтение','Обед, прогулку и чтение','Забыть про еду и прогулку'],1,'Вспомни все части истории, включая отдых.'),
      '10-13':c('После уроков у Лёвы есть тренировка, домашнее задание и время с друзьями.','Записать обязательные дела и свободное время, оставив место для отдыха.','С чего начать план?',['Записать разные дела и время отдыха','Занять каждую минуту заданиями','Ничего не учитывать'],0,'План помогает увидеть и обязанности, и свободное время.'),
      '14-17':c('У Аси учёба, дорога, проект и семейные дела; иногда она устаёт.','Замечать, когда есть силы, а когда нужен перерыв.','Что полезно учесть?',['Только дедлайны','Обязательства, время в пути и восстановление','Работу до глубокой ночи каждый день'],1,'Посмотри на весь день и свои силы.') }},
    {id:'priority',title:'Выбираем важное',rule:'Не всё надо делать одновременно. Выбери одно важное дело на ближайшее время, а остальные можно обсудить или перенести.',quiz:q('Если дел много, с чего начать?',['Выбрать важное ближайшее дело','Делать всё одновременно','Отказаться от всех перерывов'],0,'Подумай, что действительно важно сейчас.'),cases:{
      '6-9':c('Перед прогулкой нужно надеть куртку и убрать карандаши. Игрушка может подождать.','Сначала приготовить куртку, затем убрать карандаши вместе со взрослым.','Что поможет собраться на прогулку?',['Надеть куртку','Начать большую новую игру','Спрятать обувь'],0,'Выбери дело, нужное перед выходом.'),
      '10-13':c('Завтра нужно сдать задание, а новую игру можно попробовать на выходных.','Сначала наметить часть задания, затем оставить время на отдых.','Что выбрать в первую очередь?',['Посмотреть, что нужно для задания к завтра','Играть, забыв о завтрашнем задании','Сделать все задания за месяц сразу'],0,'У одного дела срок уже завтра.'),
      '14-17':c('У Миши завтра презентация и есть идея нового личного проекта без срока.','Выделить время на презентацию, а идею сохранить на потом.','Какой приоритет подходит?',['Подготовить презентацию к завтрашнему сроку','Начать проект и забыть о презентации','Работать над всем одновременно'],0,'Учитывай ближайший срок и важность.') }},
    {id:'estimate',title:'Сколько может занять дело',rule:'Оцени время примерно, выдели небольшой шаг и оставь запас. После дела можно сравнить ожидание с реальностью — это опыт, а не оценка.',quiz:q('Зачем оставлять небольшой запас времени?',['Планы иногда меняются и дело может занять больше','Чтобы не отдыхать','Потому что каждая задача длится одинаково'],0,'Оценка времени не обязана быть точной.'),cases:{
      '6-9':c('Лиза собирает рюкзак со взрослым перед выходом. Иногда найти тетрадь получается не сразу.','Начать собираться немного заранее и проверить, всё ли на месте.','Какой план поможет?',['Начать заранее и проверить рюкзак','Искать тетрадь уже после выхода','Никогда не собирать вещи'],0,'Оставь время, если что-то придётся поискать.'),
      '10-13':c('Сеня думает, что один слайд проекта займёт около 15 минут, но ещё нужна проверка.','Выделить время на слайд и небольшой запас на проверку.','Что стоит добавить к оценке?',['Небольшой запас для проверки','Ещё пять дел одновременно','Запрет на отдых'],0,'Проверка тоже занимает время.'),
      '14-17':c('Рита оценивает подготовку доклада, но ей нужно найти материалы и проверить ссылки.','Разделить подготовку на поиск, черновик и проверку с запасом.','Как составить реалистичный план?',['Учесть поиск, черновик и проверку','Запланировать только выступление','Предполагать, что задержек не бывает'],0,'У задачи есть несколько частей.') }},
    {id:'focus',title:'Внимание и перерывы',rule:'Выбери один небольшой шаг, убери то, что отвлекает, и разреши себе отдых. Если нужна помощь с настройками или условиями — обратись к взрослому.',quiz:q('Что может помочь сосредоточиться?',['Делать один небольшой шаг и сделать перерыв','Открыть много отвлекающих вкладок','Работать без еды и сна'],0,'Для внимания полезны и понятный шаг, и отдых.'),cases:{
      '6-9':c('Никита хочет закончить рисунок, но игрушки на столе мешают найти карандаши.','Вместе убрать часть игрушек и оставить карандаши.','Что можно попробовать?',['Освободить место для рисунка','Добавить на стол ещё игрушек','Отказаться от перерыва навсегда'],0,'Подготовь место для нужного дела.'),
      '10-13':c('Во время чтения планшет присылает сообщения, и Аня постоянно отвлекается.','На время чтения убрать уведомления, потом сделать перерыв.','Что может помочь?',['Отключить уведомления на время чтения','Открыть ещё несколько чатов','Читать без остановки весь день'],0,'Уменьши то, что отвлекает, и оставь отдых.'),
      '14-17':c('Олег пишет проект и каждые несколько минут проверяет сообщения.','Выбрать часть проекта, временно убрать уведомления и запланировать перерыв.','Какой подход попробовать?',['Один шаг, меньше уведомлений и перерыв','Отвечать на каждое сообщение и писать одновременно','Работать до изнеможения'],0,'Сосредоточение не требует отказа от отдыха.') }},
    {id:'flex',title:'Гибкий план дня',rule:'План нужен, чтобы помогать тебе, а не ругать за изменения. Если что-то изменилось, выбери новый шаг, сохрани время для отдыха и попроси помощи при необходимости.',quiz:q('Если день пошёл не по плану, что можно сделать?',['Пересмотреть порядок дел и оставить время на отдых','Считать день потерянным','Отменить сон, чтобы всё успеть'],0,'План можно перестроить под обстоятельства.'),cases:{
      '6-9':c('У Даши планировалась прогулка, но пошёл дождь.','Обсудить со взрослым игру дома и перенести прогулку.','Что подойдёт?',['Поиграть дома и перенести прогулку','Гулять во время сильной грозы','Решить, что весь день испорчен'],0,'Выбери безопасную замену и обсуди её.'),
      '10-13':c('После школы встреча кружка перенеслась, и у Кости появилось свободное время.','Переставить дела и оставить время для отдыха.','Что можно сделать?',['Изменить порядок дел и немного отдохнуть','Заполнить каждую минуту без перерыва','Считать план окончательно испорченным'],0,'Расписание допускает изменения.'),
      '14-17':c('У Нади внезапно добавилось семейное дело, и план подготовки к проекту сдвинулся.','Перенести необязательный шаг и уточнить срок важного дела.','Как перестроить день?',['Перенести часть задач и оставить время на восстановление','Работать всю ночь вместо сна','Не менять ничего, даже если времени нет'],0,'Пересмотри порядок и нагрузку.') }}
  ];
  window.AIPathLifeSkills = {goals,time};
})();
